var PokiServices = function() {
};
$hxClasses["PokiServices"] = PokiServices;
PokiServices.__name__ = ["PokiServices"];
PokiServices.Login = function() {
	PokiSDK.init().then(
				() => {
					console.log("Poki SDK successfully initialized");
					// your code to continue to game
					//continueToGame();
				}   
			).catch(
				() => {
					console.log("Initialized, but the user likely has adblock");
					// your code to continue to game
					//continueToGame();
				}   
			);
			PokiSDK.setDebug(false);
};
PokiServices.LoadingStart = function() {
	PokiSDK.gameLoadingStart();
};
PokiServices.LoadingEnd = function() {
	PokiSDK.gameLoadingFinished();
};
PokiServices.GameplayStart = function() {
	PokiSDK.gameplayStart();
};
PokiServices.GameplayStop = function() {
	PokiSDK.gameplayStop();
};
PokiServices.CommercialBreak = function() {
	
		SoundSystem.MuteMusic();
		Utils.DO_NOT_UPDATE = true;
		//PokiSDK.gameplayStop();
		
		PokiSDK.commercialBreak().then(
			() => {
				Utils.DO_NOT_UPDATE = false;
				SoundSystem.UnmuteMusic();
				console.log("Commercial break finished, proceeding to game");
				PokiSDK.gameplayStart();
				// your code to continue to game
			}
		);
};
PokiServices.RewardBreak = function() {
	
		PokiSDK.gameplayStop();
		SoundSystem.MuteMusic();
		Utils.DO_NOT_UPDATE = true;
	// show menu
	// when users selects rewarded option, trigger rewarded break
	PokiSDK.rewardedBreak().then(
		(success) => {
			if(success) {
			  // video was displayed, give reward
			  Utils.REWARD_GIVEN = true;
			  Utils.DO_NOT_UPDATE = false;
			  SoundSystem.UnmuteMusic();
			}
			else {
			  // video not displayed, should probably not give reward
			  Utils.DO_NOT_UPDATE = false;
			  SoundSystem.UnmuteMusic();
			}

			PokiSDK.gameplayStart();
			// your code to continue to game
			//continueToGame();
		}
	);
};
PokiServices.RewardGameOverBreak = function() {
	
		//PokiSDK.gameplayStop();
		SoundSystem.MuteMusic();
		Utils.DO_NOT_UPDATE = true;
	// show menu
	// when users selects rewarded option, trigger rewarded break
	PokiSDK.rewardedBreak().then(
		(success) => {
			if(success) {
			  // video was displayed, give reward
			  Utils.REWARD_GIVEN = true;
			  Utils.DO_NOT_UPDATE = false;
			  SoundSystem.UnmuteMusic();
			}
			else {
			  // video not displayed, should probably not give reward
			  Utils.DO_NOT_UPDATE = false;
			  SoundSystem.UnmuteMusic();
			}

			//PokiSDK.gameplayStart();
			// your code to continue to game
			//continueToGame();
		}
	);
};
