SoundSystem.Update = function() {
	if(SoundSystem.stopMusicFlag) {
		SoundSystem.musicVolume -= 0.015;
		SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		if(SoundSystem.musicVolume <= 0) {
			SoundSystem.stopMusicFlag = false;
			if(SoundSystem.musicChannel != null) {
				SoundSystem.musicChannel.stop();
			}
		}
	}
	if(SoundSystem.fadeInMusicFlag) {
		SoundSystem.musicVolume += 0.00075;
		if(SoundSystem.musicVolume >= SoundSystem.MUSIC_VOLUME) {
			SoundSystem.musicVolume = SoundSystem.MUSIC_VOLUME;
			SoundSystem.fadeInMusicFlag = false;
		}
		SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
	}
	var _g1 = 0;
	var _g = SoundSystem.sounds.length;
	while(_g1 < _g) {
		var i = _g1++;
		if(SoundSystem.sounds[i] > 0) {
			SoundSystem.sounds[i]--;
		}
	}
	SoundSystem.lastPoint = 0;
	SoundSystem.lastExplosion++;
	if(SoundSystem.lastExplosion > 10) {
		SoundSystem.lastExplosion = 10;
	}
};
SoundSystem.PlayLastMusic = function(_force) {
	if(_force == null) {
		_force = false;
	}
	SoundSystem.PlayMusic(SoundSystem.LastMusicName,-1,_force);
};
SoundSystem.PlayLevelMusic = function() {
};
SoundSystem.PlayMusic = function(musicName,_time,_forced,_fade_in) {
	if(_fade_in == null) {
		_fade_in = false;
	}
	if(_forced == null) {
		_forced = false;
	}
	if(_time == null) {
		_time = -1;
	}
	if(SoundSystem._musicTransform == null) {
		return;
	}
	if(!Utils.MusicOn) {
		return;
	}
	if(musicName == SoundSystem.LastMusicName && !_forced) {
		return;
	}
	if(SoundSystem.stopMusicFlag || Utils.IS_ANDROID) {
		SoundSystem.stopMusicFlag = false;
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.stop();
		}
	}
	if(SoundSystem.musicChannel != null) {
		if(musicName == "") {
			SoundSystem.StopMusic();
		} else {
			SoundSystem.musicChannel.stop();
		}
	}
	if(_fade_in) {
		SoundSystem.musicVolume = 0;
		SoundSystem.fadeInMusicFlag = true;
	} else {
		SoundSystem.musicVolume = SoundSystem.MUSIC_VOLUME;
	}
	SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
	if(SoundSystem.musicChannel != null) {
		SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
	}
	SoundSystem.LastMusicName = musicName;
	switch(musicName) {
	case "area_active":
		SoundSystem.musicChannel = SoundSystem.musicActiveArea.play(_time,1000000);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "area_entry":
		SoundSystem.musicChannel = SoundSystem.musicAreaEntry.play(_time,1);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "area_visited":case "visited_area":
		SoundSystem.musicChannel = SoundSystem.musicAreaVisited.play(_time,1000000);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "boss":
		SoundSystem.musicChannel = SoundSystem.musicBoss.play(_time,1000000);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "boss_intro":
		SoundSystem.musicChannel = SoundSystem.musicBossIntro.play(_time,1);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "intro":
		SoundSystem.musicChannel = SoundSystem.musicIntro.play(_time,1);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "market":
		SoundSystem.musicChannel = SoundSystem.musicShop.play(_time,1000000);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "splash":
		SoundSystem.musicChannel = SoundSystem.musicSplash.play(_time,1000000);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "victory":
		SoundSystem.musicChannel = SoundSystem.musicVictory.play(_time,1);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	}
};
SoundSystem.onLevelMusicComplete = function(event) {
	SoundSystem.PlayMusic("level",0);
};
SoundSystem.StopSound = function() {
	if(SoundSystem.soundChannel != null) {
		SoundSystem.soundChannel.stop();
	}
};
SoundSystem.StopMusic = function(instant,isAds) {
	if(isAds == null) {
		isAds = false;
	}
	if(instant == null) {
		instant = false;
	}
	if(!isAds) {
		SoundSystem.LastMusicName = "";
	}
	SoundSystem.stopMusicFlag = true;
	if(instant) {
		SoundSystem.musicVolume = 0;
	}
	if(Utils.IS_ANDROID) {
		if(instant) {
			if(SoundSystem.musicChannel != null) {
				SoundSystem.musicChannel.stop();
			}
		}
	}
};
SoundSystem.TurnOffMusicVolume = function() {
	SoundSystem.musicVolumeMultiplier = 0;
	SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
	if(SoundSystem.musicChannel != null) {
		SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
	}
};
SoundSystem.TurnOnMusicVolume = function() {
	SoundSystem.musicVolumeMultiplier = 1;
	SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
	if(SoundSystem.musicChannel != null) {
		SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
	}
};
SoundSystem.MuteMusic = function() {
	if(SoundSystem.musicChannel != null) {
		SoundSystem._musicTransform.volume = 0;
		SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
	}
};
SoundSystem.UnmuteMusic = function() {
	if(SoundSystem.musicChannel != null) {
		SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
		SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
	}
};
