		var diff_x = this.targetXPos - this.xPos;
		var diff_y = this.targetYPos - this.yPos;
		var distance = Math.sqrt(diff_x * diff_x + diff_y * diff_y);
		distance /= Utils.TILE_WIDTH;
		distance *= 0.1;
		if(!this.level.levelData.INNER_AREA.contains(this.level.hero.getMidXPos(),this.level.hero.getMidYPos())) {
			this.targetXPos = this.xPos / Utils.TILE_WIDTH | 0;
			this.targetYPos = this.yPos / Utils.TILE_HEIGHT | 0;
			distance = 0.5;
		}
		this.targetXPos *= Utils.TILE_WIDTH;
		this.targetYPos *= Utils.TILE_HEIGHT;
		this.zJumpOffset = 0;
		this.t_start_x = this.xPos;
		this.t_diff_x = this.targetXPos - this.xPos;
		this.t_start_y = this.yPos;
