interfaces_panels_TapToPlayPanel.prototype = $extend(starling_display_Sprite.prototype,{
	counter_1: null
	,counter_2: null
	,gameText: null
	,HEIGHT: null
	,IS_BLINKING: null
	,destroy: function() {
		this.removeChild(this.gameText);
		this.gameText.destroy();
		this.gameText.dispose();
		this.gameText = null;
	}
	,blink: function() {
		this.IS_BLINKING = true;
		this.gameText.set_visible(true);
		this.counter_1 = 0;
		this.counter_2 = 0;
	}
	,update: function() {
		if(this.IS_BLINKING) {
			this.counter_1++;
			if(this.counter_1 >= 4) {
				this.counter_1 = 0;
				this.gameText.set_visible(!this.gameText.get_visible());
			}
			this.counter_2++;
			if(this.counter_2 >= 60) {
				this.gameText.set_visible(true);
			}
		} else {
			this.counter_1++;
			if(this.counter_1 < 30) {
				this.gameText.set_visible(true);
			} else if(this.counter_1 >= 30 && this.counter_1 < 40) {
				this.gameText.set_visible(false);
			} else if(this.counter_1 >= 40 && this.counter_1 < 100) {
				this.gameText.set_visible(true);
			} else if(this.counter_1 >= 100 && this.counter_1 < 106) {
				this.gameText.set_visible(false);
			} else if(this.counter_1 >= 106 && this.counter_1 < 112) {
				this.gameText.set_visible(true);
			} else if(this.counter_1 >= 112 && this.counter_1 < 118) {
				this.gameText.set_visible(false);
			} else {
				this.counter_1 = -30;
			}
		}
	}
	,__class__: interfaces_panels_TapToPlayPanel
});
