	this.initPanels();
	this.initButtons();
	this.initCats();
	this.stateMachine = new game_$utils_StateMachine();
	this.stateMachine.setRule("IS_STILL_STATE","MOVE_ACTION","IS_MOVING_STATE");
	this.stateMachine.setRule("IS_SNAPPING_STATE","MOVE_ACTION","IS_MOVING_STATE");
	this.stateMachine.setRule("IS_MOVING_STATE","SNAP_ACTION","IS_SNAPPING_STATE");
	this.stateMachine.setRule("IS_SNAPPING_STATE","END_ACTION","IS_STILL_STATE");
	this.stateMachine.setFunctionToState("IS_STILL_STATE",$bind(this,this.stillAnimation));
	this.stateMachine.setFunctionToState("IS_MOVING_STATE",$bind(this,this.movingAnimation));
	this.stateMachine.setFunctionToState("IS_SNAPPING_STATE",$bind(this,this.snappingAnimation));
	this.stateMachine.setState("IS_STILL_STATE");
