var levels_backgrounds_BackgroundsManager = function(_level) {
	this.level = _level;
	if(Utils.Slot.gameVariables[55] == 0) {
		this.background = new levels_backgrounds_World1Background(this.level);
	} else if(Utils.Slot.gameVariables[55] == 1) {
		this.background = new levels_backgrounds_World2Background(this.level);
	} else if(Utils.Slot.gameVariables[55] == 2) {
		this.background = new levels_backgrounds_World3Background(this.level);
	} else if(Utils.Slot.gameVariables[55] == 3) {
		this.background = new levels_backgrounds_World4Background(this.level);
	} else if(Utils.Slot.gameVariables[55] == 4) {
		this.background = new levels_backgrounds_World5Background(this.level);
	} else if(Utils.Slot.gameVariables[55] == 5) {
		this.background = new levels_backgrounds_World6Background(this.level);
	} else {
		this.background = new levels_backgrounds_World1Background(this.level);
	}
};
