var levels_backgrounds_MenuBackground = function() {
	this.backgroundContainer = new starling_display_Sprite();
	this.backgroundContainer.set_x(this.backgroundContainer.set_y(0));
	this.backgroundContainer.set_scaleX(this.backgroundContainer.set_scaleY(Utils.GFX_SCALE));
	Utils.rootMovie.addChild(this.backgroundContainer);
	this.bgColor = new starling_display_Image(TextureManager.introTextureAtlas.getTexture("intro_black_color_2"));
	this.bgColor.set_touchable(false);
	this.bgColor.set_width(Utils.WIDTH);
	this.bgColor.set_height(Utils.HEIGHT);
	this.backgroundContainer.addChild(this.bgColor);
	this.bgColor.set_visible(false);
	this.bgImage = new starling_display_Image(TextureManager.introTextureAtlas.getTexture("intro_scene_2"));
	this.bgImage.set_touchable(false);
	this.bgImage.set_pivotX(this.bgImage.get_width() * 0.5 | 0);
	this.bgImage.set_pivotY(208);
	this.backgroundContainer.addChild(this.bgImage);
	this.bgImage.set_visible(false);
	this.bgImage.set_x(Utils.WIDTH * 0.5 | 0);
	this.bgImage.set_y(Utils.HEIGHT * 0.5 - 24 | 0);
	this.bgMoon = new starling_display_Image(TextureManager.introTextureAtlas.getTexture("dark_moon"));
	this.bgMoon.set_touchable(false);
	this.backgroundContainer.addChild(this.bgMoon);
	this.bgMoon.set_visible(false);
	this.bgMoon.set_x(Utils.WIDTH * 0.5 - 88 | 0);
	this.bgMoon.set_y(Utils.HEIGHT * 0.5 - 213 | 0);
	this.tiles = new starling_display_Sprite();
	this.tiles.set_x(this.tiles.set_y(0));
	this.backgroundContainer.addChild(this.tiles);
	this.STEP = 64;
	this.counter1 = 0;
	var i;
	var j;
	var sprite;
	var hor_amount = Math.round(Utils.SCREEN_WIDTH * Utils.GFX_INV_SCALE / this.STEP) | 0;
	var ver_amount = Math.round(Utils.SCREEN_HEIGHT * Utils.GFX_INV_SCALE / this.STEP) | 0;
	var _g1 = -1;
	var _g = ver_amount + 2;
	while(_g1 < _g) {
		var i1 = _g1++;
		var _g3 = -1;
		var _g2 = hor_amount + 2;
		while(_g3 < _g2) {
			var j1 = _g3++;
			sprite = new sprites_hud_MenuBackgroundHudSprite();
			sprite.gfxHandleClip().gotoAndStop(1);
			sprite.set_x(j1 * this.STEP);
			sprite.set_y(i1 * this.STEP);
			this.tiles.addChild(sprite);
		}
	}
};
