	,saveMarketItems: function() {
		var i;
		var mItem;
		var ITEM_0_ID = 0;
		var ITEM_1_ID = 0;
		var ITEM_2_ID = 0;
		var _g1 = 0;
		var _g = this.level.itemsManager.items.length;
		while(_g1 < _g) {
			var i1 = _g1++;
			if(this.level.itemsManager.items[i1] != null) {
				if(js_Boot.__instanceof(this.level.itemsManager.items[i1],levels_items_MarketItem)) {
					try {
						mItem = js_Boot.__cast(this.level.itemsManager.items[i1] , levels_items_MarketItem);
					} catch( e ) {
						haxe_CallStack.lastException = e;
						mItem = null;
					}
					if(mItem.SLOT_INDEX == 0) {
						ITEM_0_ID = mItem.ITEM_INDEX;
					} else if(mItem.SLOT_INDEX == 1) {
						ITEM_1_ID = mItem.ITEM_INDEX;
					} else {
						ITEM_2_ID = mItem.ITEM_INDEX;
					}
				}
			}
		}
		Utils.Slot.gameVariables[11] = ITEM_0_ID;
		if(Utils.Slot.gameVariables[15] > 0) {
			Utils.Slot.gameVariables[12] = ITEM_1_ID;
		}
		Utils.Slot.gameVariables[13] = ITEM_2_ID;
		game_$utils_SaveManager.SaveGameVariables();
	}
