var states_LogoState = function() {
};
$hxClasses["states.LogoState"] = states_LogoState;
states_LogoState.__name__ = ["states","LogoState"];
states_LogoState.__interfaces__ = [states_IState];
states_LogoState.prototype = {
	container: null
	,whiteBackground: null
	,logoImage: null
	,logoShadow: null
	,counter: null
	,counter2: null
	,scale: null
	,soundCounter: null
	,touch_counter: null
	,ALREADY_OUT: null
	,GET_OUT_FLAG: null
	,enterState: function(game) {
		this.container = new starling_display_Sprite();
		this.container.set_x(this.container.set_y(0));
		Utils.rootMovie.addChild(this.container);
		var amount_w = Utils.SCREEN_WIDTH / 320;
		var amount_h = Utils.SCREEN_HEIGHT / 282;
		if(amount_h < amount_w) {
			this.scale = amount_h | 0;
			if(amount_h < 1) {
				this.scale = 0.5;
			}
		} else {
			this.scale = amount_w | 0;
			if(amount_w < 1) {
				this.scale = 0.5;
			}
		}
		if(this.scale <= 0) {
			this.scale = 1;
		}
		this.whiteBackground = new starling_display_Quad(Utils.SCREEN_WIDTH,Utils.SCREEN_HEIGHT,2110331);
		this.whiteBackground.set_x(this.whiteBackground.set_y(0));
		this.container.addChild(this.whiteBackground);
		this.logoShadow = new starling_display_Image(TextureManager.introTextureAtlas.getTexture("neutronizedLogoShadow"));
		this.logoShadow.set_pivotX(this.logoShadow.get_width() * 0.5);
		this.logoShadow.set_pivotY(this.logoShadow.get_height() * 0.5);
		this.logoShadow.set_scaleX(this.logoShadow.set_scaleY(this.scale));
		this.logoShadow.set_x(Utils.SCREEN_WIDTH * 0.5);
		this.logoShadow.set_y(Utils.SCREEN_HEIGHT * 0.5 + 8 * this.scale);
		this.logoShadow.set_alpha(0);
		this.container.addChild(this.logoShadow);
		this.logoImage = new starling_display_Image(TextureManager.introTextureAtlas.getTexture("neutronizedLogo"));
		this.logoImage.set_pivotX(this.logoImage.get_width() * 0.5);
		this.logoImage.set_pivotY(this.logoImage.get_height() * 0.5);
		this.logoImage.set_scaleX(this.logoImage.set_scaleY(this.scale));
		this.logoImage.set_x(Utils.SCREEN_WIDTH * 0.5);
		this.logoImage.set_y(Utils.SCREEN_HEIGHT * 0.5 + 8 * this.scale);
		this.logoImage.set_alpha(0);
		this.container.addChild(this.logoImage);
		this.counter = -5;
		this.counter2 = 0;
		this.soundCounter = 0;
		Utils.rootStage.addEventListener("touch",$bind(this,this.onClick));
		Utils.rootStage.addEventListener("keyDown",$bind(this,this.keyDownListener));
		game.enterLogoState();
	}
	,keyDownListener: function(event) {
		if(this.touch_counter < 30 || this.ALREADY_OUT) {
			return;
		}
		var keyCode = event.get_keyCode();
		if(keyCode == 32) {
			if(!this.ALREADY_OUT) {
				this.ALREADY_OUT = true;
				this.GET_OUT_FLAG = true;
				SoundSystem.StopSound();
				SoundSystem.PlaySound("select");
			}
		}
	}
	,onClick: function(event) {
		if(this.touch_counter < 30 || this.ALREADY_OUT) {
			return;
		}
		var touch = event.getTouch(Utils.rootStage);
		if(touch != null) {
			if(touch.get_phase() == "ended") {
				if(!this.ALREADY_OUT) {
					this.ALREADY_OUT = true;
					this.GET_OUT_FLAG = true;
					SoundSystem.StopSound();
					SoundSystem.PlaySound("select");
				}
			}
		}
	}
	,updateState: function(game) {
		this.soundCounter++;
		this.touch_counter++;
		if(this.soundCounter == 1) {
			SoundSystem.PlaySound("logo");
		}
		this.counter++;
		if(this.logoShadow.get_alpha() == 1) {
			if(this.counter >= 6) {
				this.counter = 0;
				var _g = this.logoImage;
				_g.set_alpha(_g.get_alpha() + 0.3);
				if(this.logoImage.get_alpha() >= 1) {
					this.logoImage.set_alpha(1);
				}
			}
			this.counter2++;
			if(this.counter2 >= 4) {
				this.counter2 = 0;
				var _g1 = this.logoImage;
				_g1.set_y(_g1.get_y() - this.scale);
			}
			if(this.logoImage.get_y() <= Utils.SCREEN_HEIGHT * 0.5) {
				this.logoImage.set_y(Utils.SCREEN_HEIGHT * 0.5);
			}
		} else if(this.counter >= 8) {
			this.counter = 0;
			var _g2 = this.logoShadow;
			_g2.set_alpha(_g2.get_alpha() + 0.3);
			if(this.logoShadow.get_alpha() >= 1) {
				this.logoShadow.set_alpha(1);
				this.counter = 3;
			}
		}
		game.updateLogoState();
	}
	,exitState: function(game) {
		Utils.rootStage.removeEventListener("touch",$bind(this,this.onClick));
		Utils.rootStage.removeEventListener("keyDown",$bind(this,this.keyDownListener));
		this.container.removeChild(this.logoShadow);
		this.logoShadow.dispose();
		this.logoShadow = null;
		this.container.removeChild(this.logoImage);
		this.logoImage.dispose();
		this.logoImage = null;
		this.container.removeChild(this.whiteBackground);
		this.whiteBackground.dispose();
		this.whiteBackground = null;
		Utils.rootMovie.removeChild(this.container);
		this.container.dispose();
		this.container = null;
		game.exitLogoState();
	}
	,__class__: states_LogoState
};
var states_SettingsState = function() {
};
$hxClasses["states.SettingsState"] = states_SettingsState;
states_SettingsState.__name__ = ["states","SettingsState"];
states_SettingsState.__interfaces__ = [states_IState];
states_SettingsState.prototype = {
	menuBackground: null
	,wizardsPanel: null
	,GET_OUT_FLAG: null
	,choice: null
	,container: null
	,enterState: function(game) {
		game.enterSettingsState();
		this.menuBackground = new levels_backgrounds_MenuBackground();
		this.wizardsPanel = new interfaces_panels_SettingsCreditsPanel();
		this.GET_OUT_FLAG = false;
		this.choice = -1;
		this.container = new starling_display_Sprite();
		this.container.set_scaleX(this.container.set_scaleY(Utils.GFX_SCALE));
		this.container.set_x(this.container.set_y(0));
		Utils.rootMovie.addChild(this.container);
		Utils.rootStage.addEventListener("keyDown",$bind(this,this.keyDownListener));
		this.container.addChild(this.wizardsPanel);
		this.wizardsPanel.set_x(this.wizardsPanel.set_y(0));
	}
	,keyDownListener: function(event) {
		var keyCode = event.get_keyCode();
		haxe_Log.trace("keyCode = " + keyCode,{ fileName : "SettingsState.hx", lineNumber : 57, className : "states.SettingsState", methodName : "keyDownListener"});
		if(keyCode == 27) {
			this.wizardsPanel.GET_OUT_FLAG = true;
		}
	}
	,updateState: function(game) {
		this.menuBackground.update();
		this.wizardsPanel.update();
		if(this.wizardsPanel.GET_OUT_FLAG) {
			this.GET_OUT_FLAG = true;
			this.wizardsPanel.GET_OUT_FLAG = false;
		}
		game.updateSettingsState();
	}
	,onKeyDown: function(event) {
	}
	,exitState: function(game) {
		Utils.rootStage.removeEventListener("keyDown",$bind(this,this.keyDownListener));
		this.menuBackground.destroy();
		this.menuBackground = null;
		this.container.removeChild(this.wizardsPanel);
		this.wizardsPanel.destroy();
		this.wizardsPanel.dispose();
		this.wizardsPanel = null;
		Utils.rootMovie.removeChild(this.container);
		this.container.dispose();
		this.container = null;
		game.exitSettingsState();
	}
	,__class__: states_SettingsState
};
