	,introState: function() {
		this.gameTitle.set_visible(false);
		this.gameTitle.set_alpha(1);
		this.scale_tick = 0;
		this.PROGRESSION = 0;
		this.brightness = 1;
		this.gameTitle.set_filter(new starling_filters_ColorMatrixFilter());
		(js_Boot.__cast(this.gameTitle.get_filter() , starling_filters_ColorMatrixFilter)).adjustBrightness(this.brightness);
	}
	,introShortcutState: function() {
		this.counter_1 = this.counter_2 = 0;
		this.whiteFadeImage.set_visible(true);
		this.menuBackgroundSplash.setFinalPositions();
		SoundSystem.StopMusic();
		SoundSystem.PlayMusic("splash");
		this.gameTitle.set_filter(null);
		this.gameTitle.set_alpha(1);
		this.gameTitle.set_visible(true);
	}
	,normalState: function() {
		this.enableButtons(true);
		this.counter_1 = this.counter_2 = this.counter_3 = 0;
		this.menuBackgroundSplash.setFinalPositions();
	}
	,isTimeForCrossPromotion: function() {
		return false;
	}
	,playState: function() {
		SoundSystem.StopMusic();
		if(Utils.Slot.gameVariables[58] == 0) {
			Utils.StartNewTutorialGame();
			this.choice = 4;
		} else {
			this.choice = 0;
		}
		this.counter_1 = this.counter_2 = 0;
		this.brightness = 1;
		this.gameTitle.set_filter(new starling_filters_ColorMatrixFilter());
		(js_Boot.__cast(this.gameTitle.get_filter() , starling_filters_ColorMatrixFilter)).adjustBrightness(this.brightness);
		this.gameTitle.speedUp();
		var target_y = this.gameTitle.get_y();
		var _g = this.gameTitle;
		_g.set_y(_g.get_y() - 16);
		this.bounceTween = new starling_animation_Tween(this.gameTitle,0.5,"easeOutBounce");
		this.bounceTween.moveTo(this.gameTitle.get_x(),target_y);
		starling_core_Starling.get_current().get_juggler().add(this.bounceTween);
		this.enableButtons(false);
		this.playPanel.blink();
	}
	,crossPromotionState: function() {
	}
	,settingsState: function() {
		this.choice = 3;
		this.enableButtons(false);
	}
